script:
frappe.ui.form.on('Correspond File', {
    refresh: function(frm) {
        console.log("[DEBUG] Correspond File form refreshed.");

        // Track pagination & active tab state
        frm.eoffice_note_page = frm.eoffice_note_page || 'last';
        frm.eoffice_active_tab = frm.eoffice_active_tab || '#tab-toc';

        make_eoffice_full_width(frm);

        if (!frm.is_new()) {
            load_eoffice_data(frm);
        }

        // --- GLOBAL CLICK INTERCEPTION FOR REFERENCES ---
        if (!frm._link_interceptor_attached) {
            frm._link_interceptor_attached = true;

            $(frm.wrapper).on('click', 'a', function(e) {
                let href = $(this).attr('href');

                if (href && (href.includes('#note-') || href.includes('#dak-'))) {
                    let hashIndex = href.indexOf('#');
                    let targetId = href.substring(hashIndex + 1);

                    let targetFileMatch = href.match(/\/correspond-file\/([^\#\?]+)/);
                    let targetFile = targetFileMatch ? targetFileMatch[1] : null;

                    if (!targetFile || targetFile === frm.doc.name) {
                        e.preventDefault();
                        scroll_to_target(targetId);
                    } else {
                        sessionStorage.setItem('eoffice_scroll_target', targetId);
                    }
                }
            });
        }
    }
});


// ================================================================
// OFFICE VIEW - FULL WIDTH CSS INJECTION
// ================================================================

function make_eoffice_full_width(frm) {
    if ($('#eoffice-full-width-css').length) {
        return;
    }

    $('head').append(`
        <style id="eoffice-full-width-css">
            .form-layout,
            .form-layout .form-section,
            [data-fieldname="office_view"],
            [data-fieldname="office_view"] .section-body,
            [data-fieldname="office_view"] .row {
                width: 100% !important;
                max-width: none !important;
                margin-left: 0 !important;
                margin-right: 0 !important;
                box-sizing: border-box !important;
            }

            [data-fieldname="office_view"] .form-column {
                width: 50% !important;
                max-width: 50% !important;
                flex: 0 0 50% !important;
                box-sizing: border-box !important;
            }

            [data-fieldname="notings_display"],
            [data-fieldname="dak_display"],
            .eoffice-scroll-container {
                width: 100% !important;
                max-width: 100% !important;
                box-sizing: border-box !important;
            }
        </style>
    `);
}


// ================================================================
// CENTRALIZED DATA LOADER & RENDERER
// ================================================================

function load_eoffice_data(frm) {
    frm.clear_custom_buttons();

    frappe.call({
        method: 'correspond.correspond.doctype.correspond_file.correspond_file.get_file_and_references',
        args: { file_name: frm.doc.name },
        callback: function(r) {
            if (!r.message) return;

            let notes = r.message.notes || [];
            let daks = r.message.daks || [];
            let has_draft = notes.some(n => n.docstatus === 0);

            render_eoffice_view(frm, notes, daks, has_draft);

            if (!has_draft) {
                frm.add_custom_button('Add Note', () => {
                    add_note_inline(frm);
                }, 'Actions');
            }

            frm.add_custom_button('Create Outgoing Dak', () => {
                create_outward_dak_inline(frm);
            }, 'Actions');

            frm.add_custom_button('Forward File', () => {
                let d = new frappe.ui.Dialog({
                    title: 'Forward File to Officer',
                    fields: [
                        {
                            label: 'Forward To (User)',
                            fieldname: 'recipient',
                            fieldtype: 'Link',
                            options: 'User',
                            reqd: 1
                        },
                        {
                            label: 'Forwarding Remarks / Instructions',
                            fieldname: 'remarks',
                            fieldtype: 'Small Text',
                            reqd: 1
                        }
                    ],
                    primary_action_label: 'Confirm & Forward',
                    primary_action(values) {
                        frappe.call({
                            method: 'correspond.correspond.doctype.correspond_file.correspond_file.forward_file',
                            args: {
                                file_name: frm.doc.name,
                                recipient: values.recipient,
                                remarks: values.remarks
                            },
                            callback: function(res) {
                                if (!res.exc) {
                                    frappe.msgprint({
                                        title: 'Success',
                                        message: 'File successfully forwarded.',
                                        indicator: 'green'
                                    });
                                    d.hide();
                                    load_eoffice_data(frm);
                                }
                            }
                        });
                    }
                });
                d.show();
            }, 'Actions');
        }
    });
}


// ================================================================
// RENDER OFFICE VIEW (GREEN SHEET & TABS)
// ================================================================

function render_eoffice_view(frm, notes, daks, has_draft) {
    
    // --- DATA PREPARATION ---
    let submitted_notes = notes.filter(n => n.docstatus === 1);
    let final_daks = daks.filter(d => !d.is_draft);
    let draft_daks = daks.filter(d => d.is_draft);

    // --- LEFT PANE: GREEN SHEET (PAGINATED) ---
    let $wrapper = frm.get_field('notings_display').$wrapper;
    if ($wrapper) {
        let page_size = 5;
        let total_pages = Math.ceil(notes.length / page_size) || 1;
        
        if (frm.eoffice_note_page === 'last' || frm.eoffice_note_page > total_pages) {
            frm.eoffice_note_page = total_pages;
        }
        if (frm.eoffice_note_page < 1) frm.eoffice_note_page = 1;

        let start_idx = (frm.eoffice_note_page - 1) * page_size;
        let end_idx = Math.min(start_idx + page_size, notes.length);
        let paginated_notes = notes.slice(start_idx, end_idx);

        let html = `
            <div class="eoffice-scroll-container" style="padding: 15px; background-color: #f4fdf8; border-radius: 8px; border: 1px solid #c3e6cb; height: 75vh; overflow-y: auto; position: relative;">
                
                <!-- Header & Pagination -->
                <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #155724; padding-bottom: 10px; margin-bottom: 15px;">
                    <h4 style="color: #155724; margin: 0;">Green Sheet</h4>
                    
                    <div style="background: #e9ecef; padding: 4px 8px; border-radius: 4px; font-size: 12px; display: flex; align-items: center;">
                        <button class="btn btn-xs btn-default prev-notes-btn" style="padding: 2px 6px;"><b>&lt;</b></button>
                        <span style="margin: 0 10px; font-weight: bold; color: #495057;">
                            ${notes.length > 0 ? start_idx + 1 : 0} - ${end_idx} of ${notes.length} Note(s)
                        </span>
                        <button class="btn btn-xs btn-default next-notes-btn" style="padding: 2px 6px;"><b>&gt;</b></button>
                    </div>
                </div>
        `;

        if (has_draft) {
            html += `
                <div style="background-color: #fff3cd; color: #856404; padding: 8px; border-radius: 4px; font-size: 12px; text-align: center; margin-bottom: 15px; border: 1px solid #ffeeba;">
                    ⚠️ <b>Locked:</b> Cannot add new notes while an existing note is in Draft state.
                </div>
            `;
        }

        if (paginated_notes.length > 0) {
            paginated_notes.forEach((note, index) => {
                let actual_note_number = start_idx + index + 1; // True absolute note number
                let is_draft = (note.docstatus === 0);
                let is_green = (note.status === 'Green');

                let status_badge = '';
                let note_bg = '#fff';
                let note_border = '1px solid #e2e3e5';

                if (is_draft) {
                    if (is_green) {
                        status_badge = `
                            <button class="btn btn-xs btn-warning toggle-state-btn" data-note-name="${note.name}" data-state="Yellow" style="float: right; margin-left: 5px;">Revert to Yellow</button>
                            <button class="btn btn-xs btn-default edit-note-btn" data-note-name="${note.name}" style="float: right; margin-left: 10px; background-color: #fff; border: 1px solid #ddd;">Edit Note</button>
                            <span class="badge badge-success" style="float: right;">Green (Ready)</span>
                        `;
                        note_bg = '#e8f5e9'; 
                        note_border = '1px solid #c8e6c9';
                    } else {
                        status_badge = `
                            <button class="btn btn-xs btn-success toggle-state-btn" data-note-name="${note.name}" data-state="Green" style="float: right; margin-left: 5px;">Mark Green</button>
                            <button class="btn btn-xs btn-default edit-note-btn" data-note-name="${note.name}" style="float: right; margin-left: 10px; background-color: #fff; border: 1px solid #ddd;">Edit Note</button>
                            <span class="badge badge-warning" style="float: right;">Yellow Draft</span>
                        `;
                        note_bg = '#fffde7'; 
                        note_border = '1px solid #ffe082';
                    }
                } else {
                    status_badge = `<span class="badge badge-success" style="float: right;">Final</span>`;
                }

                html += `
                    <div id="note-${note.name}" class="target-reference-item" style="margin-bottom: 20px; border-bottom: 1px solid #c3e6cb; padding-bottom: 15px;">
                        <div style="font-size: 12px; color: #155724; margin-bottom: 8px;">
                            <b style="font-size: 14px; text-decoration: underline;">Note #${actual_note_number}</b> &nbsp;•&nbsp; 
                            <b>${note.owner}</b> • ${status_badge}
                        </div>
                        <div style="font-size: 14px; color: #333; background: ${note_bg}; padding: 10px; border-radius: 5px; border: ${note_border};">
                            ${note.note_details}
                        </div>
                    </div>
                `;
            });
        } else {
            html += `<p style="text-align: center; color: #777; margin-top: 20px;">No notings found.</p>`;
        }

        html += `</div>`;
        $wrapper.html(html);
    }


    // --- RIGHT PANE: TABBED INTERFACE ---
    let $dak_wrapper = frm.get_field('dak_display').$wrapper;
    if ($dak_wrapper) {
        
        let drafts_badge = draft_daks.length > 0 ? `<span class="badge badge-danger ml-1">${draft_daks.length}</span>` : '';

        // Determine which tab should be active based on saved state
        let toc_active = frm.eoffice_active_tab === '#tab-toc' ? 'active' : '';
        let prev_active = frm.eoffice_active_tab === '#tab-prev-notes' ? 'active' : '';
        let drafts_active = frm.eoffice_active_tab === '#tab-drafts' ? 'active' : '';

        let toc_pane_active = frm.eoffice_active_tab === '#tab-toc' ? 'show active' : '';
        let prev_pane_active = frm.eoffice_active_tab === '#tab-prev-notes' ? 'show active' : '';
        let drafts_pane_active = frm.eoffice_active_tab === '#tab-drafts' ? 'show active' : '';

        // 1. Construct Tabs using data-target instead of href to avoid Frappe routing
        let tabs_html = `
            <div style="background-color: #fff; border-radius: 8px; border: 1px solid #dee2e6; height: 75vh; display: flex; flex-direction: column;">
                
                <ul class="nav nav-tabs" id="eofficeRightTabs" role="tablist" style="background: #f8f9fa; border-top-left-radius: 8px; border-top-right-radius: 8px; padding-top: 5px; padding-left: 5px; margin-bottom: 0;">
                    <li class="nav-item">
                        <a class="nav-link ${toc_active}" data-target="#tab-toc" role="tab" style="font-weight: 600; color: #495057; cursor: pointer;">ToC</a>
                    </li>
                    <li class="nav-item">
                        <a class="nav-link ${prev_active}" data-target="#tab-prev-notes" role="tab" style="font-weight: 600; color: #495057; cursor: pointer;">Previous Notings</a>
                    </li>
                    <li class="nav-item">
                        <a class="nav-link ${drafts_active}" data-target="#tab-drafts" role="tab" style="font-weight: 600; color: #495057; cursor: pointer;">Drafts ${drafts_badge}</a>
                    </li>
                </ul>

                <div class="tab-content" id="eofficeRightTabsContent" style="flex-grow: 1; overflow-y: auto; padding: 15px;">
        `;

        // 2. ToC Tab Content (Final Daks Only)
        tabs_html += `<div class="tab-pane fade ${toc_pane_active}" id="tab-toc" role="tabpanel">`;
        if (final_daks.length > 0) {
            tabs_html += generate_dak_list_html(final_daks);
        } else {
            tabs_html += `<p style="text-align: center; color: #777; margin-top: 20px;">No finalized correspondence found.</p>`;
        }
        tabs_html += `</div>`;

        // 3. Previous Notings Tab Content (All Submitted Notes)
        tabs_html += `<div class="tab-pane fade ${prev_pane_active}" id="tab-prev-notes" role="tabpanel">`;
        tabs_html += `<div style="background-color: #f4fdf8; border-radius: 8px; border: 1px solid #c3e6cb; padding: 15px; min-height: 50vh;">`;
        if (submitted_notes.length > 0) {
            submitted_notes.forEach((note, idx) => {
                tabs_html += `
                    <div style="margin-bottom: 20px; border-bottom: 1px solid #c3e6cb; padding-bottom: 15px;">
                        <div style="font-size: 12px; color: #155724; margin-bottom: 8px;">
                            <b style="font-size: 14px; text-decoration: underline;">Note #${idx + 1}</b> &nbsp;•&nbsp; 
                            <b>${note.owner}</b>
                            <span class="badge badge-success" style="float: right;">Final</span>
                        </div>
                        <div style="font-size: 14px; color: #333; background: #fff; padding: 10px; border-radius: 5px; border: 1px solid #e2e3e5;">
                            ${note.note_details}
                        </div>
                    </div>
                `;
            });
        } else {
            tabs_html += `<p style="text-align: center; color: #777; margin-top: 20px;">No previous notings found.</p>`;
        }
        tabs_html += `</div></div>`;

        // 4. Drafts Tab Content (Draft Daks Only)
        tabs_html += `<div class="tab-pane fade ${drafts_pane_active}" id="tab-drafts" role="tabpanel">`;
        if (draft_daks.length > 0) {
            tabs_html += generate_dak_list_html(draft_daks);
        } else {
            tabs_html += `<p style="text-align: center; color: #777; margin-top: 20px;">No pending drafts.</p>`;
        }
        tabs_html += `</div>`;

        tabs_html += `</div></div>`; // Close tab-content and main wrapper

        $dak_wrapper.html(tabs_html);
    }

    // --- EVENT LISTENERS & UI BINDINGS ---
    
    // Bind Tab Switching
    $(frm.wrapper).off('click', '#eofficeRightTabs .nav-link').on('click', '#eofficeRightTabs .nav-link', function(e) {
        e.preventDefault();
        e.stopPropagation();

        let target = $(this).attr('data-target');
        frm.eoffice_active_tab = target; // Save the state

        let $parent_wrapper = frm.get_field('dak_display').$wrapper;
        
        // Remove active states from all tabs
        $parent_wrapper.find('#eofficeRightTabs .nav-link').removeClass('active');
        $parent_wrapper.find('#eofficeRightTabsContent .tab-pane').removeClass('show active');
        
        // Add active states to clicked tab
        $(this).addClass('active');
        $parent_wrapper.find(target).addClass('show active');
    });

    // Bind Pagination Buttons
    $(frm.wrapper).off('click', '.prev-notes-btn').on('click', '.prev-notes-btn', function(e) {
        e.preventDefault();
        if (frm.eoffice_note_page > 1) {
            frm.eoffice_note_page--;
            load_eoffice_data(frm);
        }
    });

    $(frm.wrapper).off('click', '.next-notes-btn').on('click', '.next-notes-btn', function(e) {
        e.preventDefault();
        let max_pages = Math.ceil(notes.length / 5);
        if (frm.eoffice_note_page < max_pages) {
            frm.eoffice_note_page++;
            load_eoffice_data(frm);
        }
    });

    // THIS WAS MISSING: Bind Edit Dak Button (Event Delegation)
    $(frm.wrapper).off('click', '.edit-dak-btn').on('click', '.edit-dak-btn', function(e) {
        e.preventDefault();
        e.stopPropagation(); // Force Frappe to ignore this click
        
        // Ensure we grab the data attribute regardless of clicking the text or the icon
        let dak_name = $(this).attr('data-dak-name'); 
        if (dak_name) {
            edit_outward_dak_inline(frm, dak_name);
        }
    });

    // Handle Scroll Targets
    setTimeout(() => {
        let storedTarget = sessionStorage.getItem('eoffice_scroll_target');
        let hash = window.location.hash;
        let targetId = storedTarget || (hash ? hash.substring(1) : null);

        if (targetId) {
            sessionStorage.removeItem('eoffice_scroll_target');
            scroll_to_target(targetId);
        }
    }, 400);

    // Bind Note Action Buttons
    if (!frm._note_listeners_attached) {
        frm._note_listeners_attached = true;

        $(frm.wrapper).on('click', '.edit-note-btn', function(e) {
            e.preventDefault();
            let note_name = $(this).attr('data-note-name');
            if (note_name) edit_note_inline(frm, note_name);
        });

        $(frm.wrapper).on('click', '.toggle-state-btn', function(e) {
            e.preventDefault();
            let note_name = $(this).attr('data-note-name');
            let target_state = $(this).attr('data-state');

            if (note_name) {
                frappe.call({
                    method: 'correspond.correspond.doctype.correspond_file.correspond_file.set_note_state',
                    args: { note_name: note_name, status: target_state },
                    callback: function(res) {
                        if (!res.exc) load_eoffice_data(frm);
                    }
                });
            }
        });
    }
}

// Helper function to keep Dak HTML rendering clean and reusable
function generate_dak_list_html(dak_array) {
    let html = '';
    dak_array.forEach(dak => {
        let attachment_icon = dak.has_attachments
            ? `<i class="fa fa-paperclip text-muted" style="margin-left: 10px; font-size: 1.1em;" title="Contains Attachments"></i>` : '';

        let badge_class = "badge-secondary";
        if (dak.label === 'Inward Dak') badge_class = "badge-primary";
        if (dak.label === 'Outward Dak') badge_class = "badge-success";
        if (dak.label === 'Linked Outward') badge_class = "badge-warning";

        let label_badge = `<span class="badge ${badge_class}" style="float: right;">${dak.label}</span>`;

        let workflow_status_badge = '';
        if (!dak.is_draft && dak.status) {
            let ws_color = "badge-secondary";
            if (dak.status === 'Dispatched' || dak.status === 'Closed') ws_color = "badge-success";
            if (dak.status === 'Approved' || dak.status === 'Marked') ws_color = "badge-info";

            workflow_status_badge = `<span class="badge ${ws_color}" style="float: right; margin-right: 8px; font-size: 10px; padding: 4px 6px;">${dak.status}</span>`;
        }

        let serial_display = dak.is_draft
            ? `<span class="badge badge-danger" style="margin-right: 5px;">DRAFT</span>`
            : `<b style="font-size: 14px; color: #155724;">#${dak.serial_no}</b> &nbsp;•&nbsp;`;

        let bg_color = dak.is_draft ? '#fff8e1' : '#fff';

        // Dynamic HTML for the Action (Edit Popup vs PDF Download)
        let action_html = '';
        if (dak.is_draft) {
            if (dak.doctype === 'Outward Dak') {
                action_html = `
                    <a href="javascript:void(0);" class="edit-dak-btn" data-dak-name="${dak.name}" title="Click to edit draft" style="font-weight: 600; color: #1f272e; text-decoration: none;">
                        <b>Subject:</b> ${dak.subject || 'Untitled'}
                        <i class="fa fa-pencil text-primary" style="margin-left: 5px;"></i>
                    </a>
                `;
            } else {
                let route_doctype = dak.doctype.toLowerCase().replace(/ /g, '-');
                let action_url = `/app/${route_doctype}/${encodeURIComponent(dak.name)}`;
                action_html = `
                    <a href="${action_url}" target="_blank" title="Click to open and edit draft" style="font-weight: 600; color: #1f272e; text-decoration: none;">
                        <b>Subject:</b> ${dak.subject || 'Untitled'}
                        <i class="fa fa-pencil text-primary" style="margin-left: 5px;"></i>
                    </a>
                `;
            }
        } else {
            let action_url = `/api/method/frappe.utils.print_format.download_pdf?doctype=${encodeURIComponent(dak.doctype)}&name=${encodeURIComponent(dak.name)}&format=Standard&no_letterhead=0`;
            action_html = `
                <a href="${action_url}" target="_blank" title="Click to download PDF" style="font-weight: 600; color: #1f272e; text-decoration: none;">
                    <b>Subject:</b> ${dak.subject || 'Untitled'}
                    <i class="fa fa-file-pdf-o text-danger" style="margin-left: 5px;"></i>
                </a>
            `;
        }

        html += `
            <div id="dak-${dak.name}" class="target-reference-item" style="margin-bottom: 20px; border-bottom: 1px solid #dee2e6; padding-bottom: 15px; background: ${bg_color}; padding: 10px; border-radius: 5px; border: 1px solid #ced4da;">
                <div style="font-size: 12px; color: #495057; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center;">
                    <div>${serial_display} <b>ID:</b> ${dak.name}</div>
                    <div>${workflow_status_badge} ${label_badge}</div>
                </div>
                <div style="font-size: 14px; color: #333; margin-top: 5px;">
                    ${action_html}
                    ${attachment_icon}
                </div>
            </div>
        `;
    });
    return html;
}

// ================================================================
// SCROLL TO REFERENCE & DIALOG HELPERS
// ================================================================

function scroll_to_target(targetId) {
    let $target = $('#' + targetId);

    if ($target.length) {
        let $container = $target.closest('.eoffice-scroll-container');

        if ($container.length) {
            let containerTop = $container.scrollTop();
            let elementTop = $target.position().top;
            let targetScrollPos = containerTop + elementTop - ($container.height() / 2) + ($target.height() / 2);

            $container.animate({ scrollTop: targetScrollPos }, 500);
        } else {
            $target[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
        }

        $target.css('background-color', '#fff3cd');
        setTimeout(() => {
            $target.css('background-color', 'transparent');
        }, 2000);
    }
}

function add_note_inline(frm) {
    let parent_file = frm.doc.name;

    let d = new frappe.ui.Dialog({
        title: 'Add New Note',
        fields: [
            {
                label: '🔗 Quick Reference Tool',
                fieldname: 'ref_helper_html',
                fieldtype: 'HTML',
                options: `
                    <div style="margin-bottom: 10px;">
                        <button type="button" class="btn btn-xs btn-default" id="dialog-insert-ref-btn">
                            <i class="fa fa-link"></i> Insert Reference Link
                        </button>
                    </div>
                `
            },
            {
                label: 'Note Details',
                fieldname: 'note_details',
                fieldtype: 'Text Editor',
                reqd: 1
            }
        ],
        size: 'large',
        primary_action_label: 'Save as Draft',
        primary_action(values) {
            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype: 'Correspond Noting',
                        file: parent_file,
                        note_details: values.note_details,
                        status: 'Yellow'
                    }
                },
                callback: function(r) {
                    if (!r.exc) {
                        frappe.msgprint({ title: 'Success', message: 'Draft note created.', indicator: 'green' });
                        d.hide();
                        load_eoffice_data(frm);
                    }
                }
            });
        }
    });

    d.show();

    setTimeout(() => {
        d.$wrapper.find('#dialog-insert-ref-btn').on('click', function(e) {
            e.preventDefault();
            show_popup_reference_dialog(parent_file, d);
        });
    }, 200);
}

function edit_note_inline(frm, note_name) {
    let parent_file = frm.doc.name;

    frappe.db.get_value('Correspond Noting', note_name, 'note_details')
    .then(r => {
        let current_text = r.message ? r.message.note_details : '';

        let d = new frappe.ui.Dialog({
            title: 'Edit Draft Note',
            fields: [
                {
                    label: '🔗 Quick Reference Tool',
                    fieldname: 'ref_helper_html',
                    fieldtype: 'HTML',
                    options: `
                        <div style="margin-bottom: 10px;">
