// ================================================================

function show_popup_reference_dialog(file_name, parent_dialog) {
    frappe.call({
        method: 'correspond.correspond.doctype.correspond_file.correspond_file.get_file_and_references',
        args: { file_name: file_name },
        callback: function(r) {
            if (!r.message) return;

            let files = r.message.files || [file_name];
            let notes = r.message.notes || [];
            let daks = r.message.daks || [];

            let file_options = files.map(f => f === file_name ? `${f} (Current File)` : f);

            let ref_d = new frappe.ui.Dialog({
                title: 'Insert File Reference',
                fields: [
                    {
                        label: 'Reference Category',
                        fieldname: 'ref_category',
                        fieldtype: 'Select',
                        options: 'Note\nDak',
                        default: 'Note',
                        change: function() { update_target_dropdown(); }
                    },
                    {
                        label: 'Select File',
                        fieldname: 'target_file',
                        fieldtype: 'Select',
                        options: file_options,
                        default: file_options[0],
                        change: function() { update_target_dropdown(); }
                    },
                    {
                        label: 'Select Document',
                        fieldname: 'selected_doc',
                        fieldtype: 'Select',
                        options: [],
                        reqd: 1
                    },
                    {
                        label: 'Custom Link Text (Optional)',
                        fieldname: 'link_text',
                        fieldtype: 'Data'
                    }
                ],
                primary_action_label: 'Insert Into Note',
                primary_action(values) {
                    let category = values.ref_category;
                    let actual_file = values.target_file.replace(' (Current File)', '');
                    let doc_name = values.selected_doc;

                    if (!doc_name) return;

                    let prefix = category === 'Note' ? 'note' : 'dak';
                    let url = `/app/correspond-file/${actual_file}#${prefix}-${doc_name}`;
                    let display_text = values.link_text ? values.link_text : `${category} (${doc_name})`;

                    let field = parent_dialog.fields_dict['note_details'];
                    if (field && field.quill) {
                        let range = field.quill.getSelection();
                        if (range && range.length > 0) {
                            field.quill.formatText(range.index, range.length, 'link', url);
                        } else {
                            let cursor_pos = range ? range.index : field.quill.getLength();
                            field.quill.insertText(cursor_pos, ` [${display_text}] `, 'link', url);
                        }
                    } else {
                        let current_val = parent_dialog.get_value('note_details') || '';
                        parent_dialog.set_value('note_details', current_val + ` <a href="${url}">[${display_text}]</a> `);
                    }

                    ref_d.hide();
                }
            });

            function update_target_dropdown() {
                let category = ref_d.get_value('ref_category');
                let selected_file = (ref_d.get_value('target_file') || file_options[0]).replace(' (Current File)', '');
                let doc_options = [];

                if (category === 'Note') {
                    notes.filter(n => n.file === selected_file).forEach((note, index) => {
                        let text_only = $('<div>').html(note.note_details || '').text();
                        let snippet = text_only.length ? text_only.substring(0, 25) + '...' : '';
                        doc_options.push({ label: `Note #${index + 1}: ${snippet} (${note.name})`, value: note.name });
                    });
                } else {
                    daks.forEach(dak => {
                        doc_options.push({ label: `Dak: ${dak.name} - ${dak.subject || 'Untitled'}`, value: dak.name });
                    });
                }

                let select_field = ref_d.fields_dict['selected_doc'];
                select_field.df.options = doc_options.length > 0 ? doc_options.map(o => o.label) : ['No records found'];
                select_field.refresh();

                ref_d.doc_mapping = {};
                doc_options.forEach(o => { ref_d.doc_mapping[o.label] = o.value; });
            }

            let original_action = ref_d.primary_action;
            ref_d.set_primary_action('Insert Into Note', function() {
                let values = ref_d.get_values();
                if (!values) return;
                values.selected_doc = ref_d.doc_mapping ? ref_d.doc_mapping[values.selected_doc] : values.selected_doc;
                original_action(values);
            });

            ref_d.show();
            update_target_dropdown();
        }
    });
}

frappe.ui.form.on('Correspond Noting', {
    refresh: function(frm) {
        // Remove any existing custom reference button to prevent duplicates
        $(frm.wrapper).find('.custom-ref-btn-row').remove();

        // Create a dedicated reference insertion bar right underneath the text editor
        let $ref_container = $(`
            <div class="custom-ref-btn-row" style="margin-top: 10px; margin-bottom: 15px; padding: 10px; background: #f8f9fa; border: 1px dashed #ced4da; border-radius: 4px; display: flex; align-items: center; justify-content: space-between;">
                <span style="font-size: 12px; color: #6c757d;"><b>eOffice Tools:</b> Insert a hyperlinked reference to a previous note, dak, or attached file.</span>
                <button type="button" class="btn btn-sm btn-primary btn-insert-reference">
                    <i class="fa fa-link"></i> Insert Reference Link
                </button>
            </div>
        `);

        // Insert this bar right after the 'note_details' field wrapper
        let field_wrapper = frm.get_field('note_details').$wrapper;
        if (field_wrapper) {
            field_wrapper.after($ref_container);

            // Bind click event to open the reference dialog
            $ref_container.find('.btn-insert-reference').on('click', function() {
                show_inline_reference_dialog(frm);
            });
        }
    }
});

function show_inline_reference_dialog(frm) {
    let d = new frappe.ui.Dialog({
        title: 'Insert File Reference',
        fields: [
            { 
                label: 'Reference Type', 
                fieldname: 'ref_type', 
                fieldtype: 'Select', 
                options: 'Correspond Noting\nCorrespond Dak\nAttached File', 
                reqd: 1 
            },
            { 
                label: 'Select Target Document', 
                fieldname: 'ref_doc', 
                fieldtype: 'Dynamic Link', 
                options: 'ref_type', 
                reqd: 1,
                get_query: function() {
                    return {
                        filters: {
                            'file': frm.doc.file
                        }
                    };
                }
            },
            {
                label: 'Custom Link Text (Optional)',
                fieldname: 'link_text',
                fieldtype: 'Data',
                description: 'E.g., "See Note #2" or "Refer to Letter dt. 10.08.2026". If blank, the Doc ID will be used.'
            }
        ],
        primary_action_label: 'Insert Into Note',
        primary_action(values) {
            let url = `/app/${values.ref_type.toLowerCase().replace(' ', '-')}/${values.ref_doc}`;
            let display_text = values.link_text ? values.link_text : values.ref_doc;
            
            let field = frm.fields_dict['note_details'];
            if (field && field.quill) {
                let range = field.quill.getSelection();
                let cursor_pos = range ? range.index : field.quill.getLength();
                
                // Insert the formatted hyperlink directly into the Quill editor at cursor position
                field.quill.insertText(cursor_pos, ` [${display_text}] `, 'link', url);
            } else {
                // Fallback if quill instance isn't directly caught
                let current_val = frm.doc.note_details || '';
                frm.set_value('note_details', current_val + ` <a href="${url}" target="_blank">[${display_text}]</a> `);
            }
            d.hide();
        }
    });
    d.show();
}
